const profiles=(run,target)=>target==='professor'
 ?{invitation:professorInvitationProfileV37(run),chat:[0,1].map(index=>professorMealChatProfileV37(run,index))}
 :CAST_IDS_V39.includes(target)
 ?{invitation:castInvitationProfileV39(run,target),chat:[0,1].map(index=>castMealChatProfileV39(run,target,index))}
 :CAST_IDS_V65.includes(target)
 ?{invitation:castInvitationProfileV65(run,target),chat:[0,1].map(index=>castMealChatProfileV65(run,target,index))}
 :{invitation:invitationProfileV34(run,target),chat:[0,1].map(index=>mealChatProfileV36(run,target,index))};
const replayCase=record=>{
 const before=E.replayRun(record.roleId,record.seed,record.beforeActions);
 assert.equal(E.validRun(before),true);assert.ok(before.patronage);assert.equal(E.canRequestPatronageReply(before),true);assert.ok(E.getPatronageReplyTargets(before).includes(record.target));
 const snapshot=structuredClone(before),pending=E.requestPatronageReply(before,record.target),after=E.advance(pending),row=pending.history.at(-1);
 assert.notEqual(pending,before);assert.deepEqual(before,snapshot);
 assert.equal(E.validRun(pending),true);assert.equal(E.validRun(after),true);assert.deepEqual(E.replayRun(after.roleId,after.seed,after.actions),after);
 return {before,pending,after,row,beforeProfiles:profiles(before,record.target),afterProfiles:profiles(after,record.target)};
};

test('only strict fresh r68 seeds use the familiarity correction',()=>{
 for(const kind of ['n','s','d']){
  const seed='e39-r68-'+kind+'-'+ 'a'.repeat(22);assert.equal(isPatronageFamiliarityV68(seed),true);assert.equal(isPatronageFamiliarityV68({seed}),true);
 }
 for(const seed of ['e39-r67-n-'+'a'.repeat(22),'e39-r69-n-'+'a'.repeat(22),'e39-r68-x-'+'a'.repeat(22),'e39-r68-n-'+'a'.repeat(21),'e39-r68-n-'+'a'.repeat(23),'e39-r68-n-'+'A'.repeat(22),'e39-r68-n-'+'g'.repeat(22),'e39-r68-n-'+'a'.repeat(22)+'-extra',null])assert.equal(isPatronageFamiliarityV68(seed),false);
});

test('natural negative r68 replies to every public character preserve encounters but cannot improve a meal through extra familiarity',()=>{
 const records=NATURAL_CASES.filter(row=>row.key.startsWith('negative-target-'));
 assert.equal(records.length,28);assert.deepEqual(records.map(row=>row.target).sort(),Object.keys(PERSONAS).sort());
 for(const record of records){
  const {before,after,row,beforeProfiles:b,afterProfiles:a}=replayCase(record);
  assert.match(record.seed,/^e39-r68-[sd]-[0-9a-f]{22}$/);assert.equal(row.patronageOutcome.affinityDelta,record.affinityDelta);assert.ok(row.patronageOutcome.affinityDelta<0);
  assert.equal(countsFriendlyPatronageEncounterV68(after,row),false);
  assert.equal(a.invitation.familiarity,b.invitation.familiarity,record.target);
  assert.ok(a.invitation.acceptChance<=b.invitation.acceptChance,record.target+' invitation');
  assert.ok(a.invitation.affinity<=b.invitation.affinity,record.target+' affinity');
  for(const index of [0,1]){assert.ok(a.chat[index].warmChance<=b.chat[index].warmChance,record.target+' chat '+index);assert.ok(a.chat[index].mineChance>=b.chat[index].mineChance,record.target+' mine '+index);}
  const previous=deriveCharacterStats(before).find(item=>item.id===record.target),current=deriveCharacterStats(after).find(item=>item.id===record.target);
  assert.equal(current.encounters,previous.encounters+1,'the encounter still belongs in the character book');
  assert.ok(characterAffinity(after,record.target).score<=characterAffinity(before,record.target).score);
  for(const key of ['turn','rank','pay','basePay','pip','pipCount','patronage','resumeEventId'])assert.deepEqual(after[key],before[key],record.target+'/'+key);
 }
});

test('genuine positive cooperation still increases friendly familiarity across all four guest-profile implementations',()=>{
 const records=NATURAL_CASES.filter(row=>row.key.startsWith('positive-'));assert.equal(records.length,4);
 assert.deepEqual(records.map(row=>row.key).sort(),['positive-original','positive-professor','positive-cast39','positive-cast65'].sort());
 for(const record of records){
  const {after,row,beforeProfiles:b,afterProfiles:a}=replayCase(record);assert.ok(row.patronageOutcome.affinityDelta>0);
  assert.equal(countsFriendlyPatronageEncounterV68(after,row),true);assert.equal(a.invitation.familiarity,b.invitation.familiarity+1);
  assert.ok(a.invitation.acceptChance>=b.invitation.acceptChance);
  for(const index of [0,1])assert.ok(a.chat[index].warmChance>=b.chat[index].warmChance);
 }
});

test('three independent r67/r68 character pairs reproduce the old counterexample and prove the corrected direction without changing r67 results',()=>{
 assert.deepEqual(LEGACY_CASES.map(row=>row.target).sort(),['kind','jonathan','owen'].sort());
 for(const legacy of LEGACY_CASES){
  const old=replayCase(legacy);assert.match(legacy.seed,/^e39-r67-/);assert.equal(isPatronageFamiliarityV68(old.after),false);
  assert.deepEqual(old.beforeProfiles.invitation,legacy.before);assert.deepEqual(old.afterProfiles.invitation,legacy.after);
  assert.deepEqual(old.beforeProfiles.chat[0],legacy.beforeChat);assert.deepEqual(old.afterProfiles.chat[0],legacy.afterChat);
  assert.equal(createHash('sha256').update(JSON.stringify(old.after)).digest('hex'),legacy.afterSha256);
  assert.ok(old.row.patronageOutcome.affinityDelta<0);assert.equal(countsFriendlyPatronageEncounterV68(old.after,old.row),true);
  assert.equal(old.afterProfiles.invitation.familiarity,old.beforeProfiles.invitation.familiarity+1);
  assert.ok(old.afterProfiles.invitation.acceptChance>old.beforeProfiles.invitation.acceptChance,'published r67 preserves its original deterministic rules');
  const fresh=NATURAL_CASES.find(row=>row.key==='negative-target-'+legacy.target),next=replayCase(fresh);
  assert.notEqual(fresh.seed,legacy.seed);assert.ok(next.row.patronageOutcome.affinityDelta<0);
  assert.equal(next.afterProfiles.invitation.familiarity,next.beforeProfiles.invitation.familiarity);
  assert.ok(next.afterProfiles.invitation.acceptChance<=next.beforeProfiles.invitation.acceptChance);
  assert.ok(next.afterProfiles.chat[0].warmChance<=next.beforeProfiles.chat[0].warmChance);
 }
});
